SELECT (DATE_TRUNC('DAY', "STARTED_AT")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(ELAPSED_MS)) = 0 OR (SUM(ELAPSED_MS)) IS NULL THEN NULL ELSE CAST((SUM(QUEUED_OVERLOAD_MS + QUEUED_PROVISIONING_MS)) AS DECIMAL(38, 15)) / CAST((SUM(ELAPSED_MS)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "Q_QUEUE_SHARE" FROM (SELECT q."QUERY_ID" AS QUERY_ID, (TRY_TO_TIMESTAMP_NTZ(q."START_TIME")) AS STARTED_AT, q."WAREHOUSE_NAME" AS WAREHOUSE_NAME, q."WAREHOUSE_SIZE" AS WAREHOUSE_SIZE, q."USER_NAME" AS USER_NAME, q."ROLE_NAME" AS ROLE_NAME, q."DATABASE_NAME" AS DATABASE_NAME, q."QUERY_TYPE" AS QUERY_TYPE, q."EXECUTION_STATUS" AS EXECUTION_STATUS, q."ERROR_CODE" AS ERROR_CODE, q."QUERY_PARAMETERIZED_HASH" AS FINGERPRINT, (JSON_EXTRACT_PATH_TEXT(q."QUERY_TAG", 'team')) AS QUERY_TAG_TEAM, q."TOTAL_ELAPSED_TIME" AS ELAPSED_MS, q."COMPILATION_TIME" AS COMPILATION_MS, q."EXECUTION_TIME" AS EXECUTION_MS, q."QUEUED_OVERLOAD_TIME" AS QUEUED_OVERLOAD_MS, q."QUEUED_PROVISIONING_TIME" AS QUEUED_PROVISIONING_MS, q."BYTES_SCANNED" AS BYTES_SCANNED, q."BYTES_SPILLED_TO_LOCAL_STORAGE" AS BYTES_SPILLED_LOCAL, q."BYTES_SPILLED_TO_REMOTE_STORAGE" AS BYTES_SPILLED_REMOTE, q."PARTITIONS_SCANNED" AS PARTITIONS_SCANNED, q."PARTITIONS_TOTAL" AS PARTITIONS_TOTAL, q."PERCENTAGE_SCANNED_FROM_CACHE" AS CACHE_FRACTION, (CAST(COALESCE(a."CREDITS_ATTRIBUTED_COMPUTE", 0) AS DECIMAL(38, 9))) AS CREDITS_ATTRIBUTED FROM query_history AS q LEFT JOIN query_attribution_history AS a ON a."QUERY_ID" = q."QUERY_ID") AS base GROUP BY (DATE_TRUNC('DAY', "STARTED_AT")) ORDER BY "Q_QUEUE_SHARE" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
